/** CSS custom property name for a token path, e.g. cssVar('color.sea.500') -> "var(--df-color-sea-500)" */
export function cssVar(path: string): string {
  return 'var(' + cssVarName(path) + ')';
}

/** Raw custom property name (without var()). */
export function cssVarName(path: string): string {
  return (
    '--df-' +
    path
      .split('.')
      .map((segment) => segment.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase())
      .join('-')
  );
}

